{
  "findings": [
    {
      "check_id": "CKV_AZURE_3",
      "title": "Ensure that 'enable_https_traffic_only' is enabled",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "MEDIUM",
      "explanation": "Disabling HTTPS traffic only allows unencrypted HTTP connections to the storage account."
    },
    {
      "check_id": "CKV_AZURE_44",
      "title": "Ensure Storage Account is using the latest version of TLS encryption",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "MEDIUM",
      "explanation": "Using an outdated TLS version may expose the storage account to known vulnerabilities."
    }
  ],
  "patched_code": "resource \"azurerm_storage_account\" \"notification_storage\" {\n  name                     = \"smartgridscada${random_string.suffix.result}\"\n  resource_group_name      = azurerm_resource_group.smart_grid_rg.name\n  location                 = azurerm_resource_group.smart_grid_rg.location\n  account_tier             = \"Standard\"\n  account_replication_type = \"LRS\"\n  enable_https_traffic_only = true\n  min_tls_version          = \"TLS1_2\"\n}",
  "fix_summary": "Enabled HTTPS traffic only and set the minimum TLS version to 1.2 for the storage account."
}
